@page "/settings"
@using sv_5a84828286dc464db1d58fa1676c4993.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <aside class="settings-sidebar">
        <h3 class="sidebar-title">Settings</h3>
        <nav class="sidebar-nav">
            @foreach (var section in _sections)
            {
                <button class="sidebar-item @(section == _activeSection ? "active" : "")"
                        @onclick="() => SetActiveSection(section)">
                    <span class="sidebar-icon">@GetSectionIcon(section)</span>
                    @section
                </button>
            }
        </nav>
    </aside>

    <main class="settings-main">
        @if (_loading)
        {
            <div class="loading-spinner">
                <div class="spinner"></div>
                <p>Loading settings…</p>
            </div>
        }
        else
        {
            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (_toastVisible)
        {
            <div class="toast-message @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastText
            </div>
        }
    </main>
</div>

@* ─── Section render fragments ─── *@

@{
    RenderFragment RenderProfileSection() =>
        @<section class="settings-section">
            <h2>Profile</h2>
            <p class="section-description">Manage your personal information and public profile.</p>

            <div class="avatar-area">
                <img src="@_profileAvatarUrl" alt="Avatar" class="avatar-preview" />
                <div class="avatar-url-display">
                    <label>Avatar URL</label>
                    <input type="text" value="@_profileAvatarUrl" @onchange="e => _profileAvatarUrl = e.Value?.ToString() ?? string.Empty" />
                </div>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_profileDisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_profileEmail" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="_profileBio"></textarea>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>;

    RenderFragment RenderNotificationsSection() =>
        @<section class="settings-section">
            <h2>Notifications</h2>
            <p class="section-description">Choose how and when you want to be notified.</p>

            <div class="toggle-group">
                <div class="toggle-row">
                    <label>Email Notifications</label>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_notifEmail" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>
                <div class="toggle-row">
                    <label>Push Notifications</label>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_notifPush" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>
                <div class="toggle-row">
                    <label>Weekly Digest</label>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_notifWeeklyDigest" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>
            </div>

            <h4>Muted Channels</h4>
            <div class="channel-list">
                @foreach (var channel in MockSettingsService.AvailableChannels)
                {
                    var ch = channel;
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(ch)"
                               @onchange="e => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                        <span class="channel-name">#@ch</span>
                        @if (_mutedChannels.Contains(ch))
                        {
                            <span class="muted-badge">muted</span>
                        }
                    </label>
                }
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>;

    RenderFragment RenderSecuritySection() =>
        @<section class="settings-section">
            <h2>Security</h2>
            <p class="section-description">Manage your password, two-factor authentication, and active sessions.</p>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="panel-chevron @(_passwordPanelOpen ? "open" : "")">▸</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm Password</label>
                            <input id="confirmPwd" type="password" @bind="_confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <p class="field-error">@_passwordError</p>
                        }
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-row" style="margin-top:1.5rem;">
                <div>
                    <label>Two-Factor Authentication</label>
                    <span class="status-badge @(_twoFactorEnabled ? "status-on" : "status-off")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <label class="toggle-switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="toggle-slider"></span>
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange != null)
            {
                <p class="hint-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h4 style="margin-top:2rem;">Active Sessions</h4>
            <div class="table-responsive">
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (_securitySettings != null)
                        {
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != _securitySettings.Sessions.FirstOrDefault()?.Id)
                                        {
                                            <button class="btn btn-danger btn-sm"
                                                    @onclick="() => ConfirmRevokeSession(session.Id, session.Device)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>

            @if (_showRevokeConfirm)
            {
                <div class="modal-overlay" @onclick="CancelRevoke">
                    <div class="modal-dialog" @onclick:stopPropagation="true">
                        <h4>Revoke Session</h4>
                        <p>Are you sure you want to revoke the session on <strong>@_revokeDeviceName</strong>? The user will be logged out on that device.</p>
                        <div class="button-row">
                            <button class="btn btn-danger" @onclick="ExecuteRevoke">Revoke</button>
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>;

    RenderFragment RenderAppearanceSection() =>
        @<section class="settings-section">
            <h2>Appearance</h2>
            <p class="section-description">Customize how the application looks and feels.</p>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        var t = theme;
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@t"
                                   checked="@(_appTheme == t)"
                                   @onchange="() => _appTheme = t" />
                            @t
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        var s = size;
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@s"
                                   checked="@(_appFontSize == s)"
                                   @onchange="() => _appFontSize = s" />
                            @s
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_appLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Portuguese">Portuguese</option>
                </select>
            </div>

            <div class="toggle-row">
                <label>Compact Mode</label>
                <label class="toggle-switch">
                    <input type="checkbox" @bind="_appCompactMode" />
                    <span class="toggle-slider"></span>
                </label>
            </div>

            <h4 style="margin-top:1.5rem;">Preview</h4>
            <div class="appearance-preview @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-body">This is a preview of your selected appearance settings. The theme, font size, and compact mode are reflected here.</p>
                <div class="preview-actions">
                    <button class="preview-btn primary">Primary Action</button>
                    <button class="preview-btn secondary">Secondary</button>
                </div>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>;
}

@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";
    private bool _loading = true;

    // Toast
    private bool _toastVisible;
    private string _toastText = string.Empty;
    private bool _toastIsError;

    // Profile
    private string _profileDisplayName = string.Empty;
    private string _profileEmail = string.Empty;
    private string _profileAvatarUrl = string.Empty;
    private string _profileBio = string.Empty;
    private UserProfile? _savedProfile;

    // Notifications
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifWeeklyDigest;
    private List<string> _mutedChannels = [];

    // Security
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelOpen;
    private string _currentPassword = string.Empty;
    private string _newPassword = string.Empty;
    private string _confirmPassword = string.Empty;
    private string _passwordError = string.Empty;
    private bool _twoFactorEnabled;
    private bool _showRevokeConfirm;
    private string _revokeSessionId = string.Empty;
    private string _revokeDeviceName = string.Empty;

    // Appearance
    private string _appTheme = "Light";
    private string _appFontSize = "Medium";
    private string _appLanguage = "English";
    private bool _appCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        ApplyProfile(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        _notifEmail = notifs.EmailNotifications;
        _notifPush = notifs.PushNotifications;
        _notifWeeklyDigest = notifs.WeeklyDigest;
        _mutedChannels = new List<string>(notifs.MutedChannels);

        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        var appearance = await SettingsService.GetAppearanceAsync();
        _appTheme = appearance.Theme;
        _appFontSize = appearance.FontSize;
        _appLanguage = appearance.Language;
        _appCompactMode = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    private void SetActiveSection(string section) => _activeSection = section;

    // ─── Profile ───

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully.");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile != null)
        {
            ApplyProfile(_savedProfile);
        }
    }

    // ─── Notifications ───

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifWeeklyDigest, new List<string>(_mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved.");
    }

    // ─── Security ───

    private async Task UpdatePassword()
    {
        _passwordError = string.Empty;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = string.Empty;
        _newPassword = string.Empty;
        _confirmPassword = string.Empty;
        _passwordPanelOpen = false;
        await ShowToast("Password updated successfully.");
    }

    private void ConfirmRevokeSession(string sessionId, string deviceName)
    {
        _revokeSessionId = sessionId;
        _revokeDeviceName = deviceName;
        _showRevokeConfirm = true;
    }

    private async Task ExecuteRevoke()
    {
        await SettingsService.RevokeSessionAsync(_revokeSessionId);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _showRevokeConfirm = false;
        await ShowToast("Session revoked.");
    }

    private void CancelRevoke() => _showRevokeConfirm = false;

    // ─── Appearance ───

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_appTheme.ToLowerInvariant()} preview-font-{_appFontSize.ToLowerInvariant()}";
        if (_appCompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_appTheme, _appFontSize, _appLanguage, _appCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved.");
    }

    // ─── Helpers ───

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private async Task ShowToast(string text, bool isError = false)
    {
        _toastText = text;
        _toastIsError = isError;
        _toastVisible = true;
        StateHasChanged();
        await Task.Delay(3000);
        _toastVisible = false;
        StateHasChanged();
    }
}

/* ─── Layout ─── */

.settings-container {
    display: flex;
    min-height: calc(100vh - 3.5rem);
    background: #f8f9fa;
}

.settings-sidebar {
    width: 240px;
    background: #fff;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.sidebar-title {
    font-size: 1.1rem;
    font-weight: 600;
    padding: 0 1.25rem 1rem;
    margin: 0;
    color: #333;
}

.sidebar-nav {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.7rem 1.25rem;
    border: none;
    background: none;
    font-size: 0.925rem;
    color: #555;
    cursor: pointer;
    text-align: left;
    transition: background 0.15s, color 0.15s;
    width: 100%;
}

.sidebar-item:hover {
    background: #f0f0f0;
    color: #111;
}

.sidebar-item.active {
    background: #e8f0fe;
    color: #1a73e8;
    font-weight: 600;
    border-left: 3px solid #1a73e8;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* ─── Main content ─── */

.settings-main {
    flex: 1;
    padding: 2rem 2.5rem;
    position: relative;
    max-width: 800px;
}

.settings-section h2 {
    margin: 0 0 0.25rem;
    font-size: 1.5rem;
    color: #222;
}

.section-description {
    color: #666;
    margin-bottom: 1.5rem;
}

/* ─── Forms ─── */

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.35rem;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.55rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.925rem;
    transition: border-color 0.15s;
    background: #fff;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #1a73e8;
    box-shadow: 0 0 0 3px rgba(26, 115, 232, 0.12);
}

/* ─── Buttons ─── */

.button-row {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.55rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    border: 1px solid transparent;
    transition: background 0.15s, box-shadow 0.15s;
}

.btn-primary {
    background: #1a73e8;
    color: #fff;
}

.btn-primary:hover {
    background: #1557b0;
}

.btn-secondary {
    background: #fff;
    color: #333;
    border-color: #ccc;
}

.btn-secondary:hover {
    background: #f5f5f5;
}

.btn-danger {
    background: #dc3545;
    color: #fff;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* ─── Avatar ─── */

.avatar-area {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e0e0e0;
}

.avatar-url-display {
    flex: 1;
}

.avatar-url-display label {
    display: block;
    font-weight: 500;
    font-size: 0.85rem;
    margin-bottom: 0.3rem;
    color: #555;
}

.avatar-url-display input {
    width: 100%;
    padding: 0.45rem 0.65rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.85rem;
}

/* ─── Toggle switches ─── */

.toggle-group {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 0.25rem 0;
    margin-bottom: 1.5rem;
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.85rem 1rem;
}

.toggle-group .toggle-row + .toggle-row {
    border-top: 1px solid #f0f0f0;
}

.toggle-switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
    flex-shrink: 0;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.toggle-slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background: #ccc;
    border-radius: 24px;
    transition: background 0.2s;
}

.toggle-slider::before {
    content: "";
    position: absolute;
    width: 18px;
    height: 18px;
    left: 3px;
    bottom: 3px;
    background: #fff;
    border-radius: 50%;
    transition: transform 0.2s;
}

.toggle-switch input:checked + .toggle-slider {
    background: #1a73e8;
}

.toggle-switch input:checked + .toggle-slider::before {
    transform: translateX(20px);
}

/* ─── Channels ─── */

.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.5rem 0.75rem;
    background: #fff;
    border: 1px solid #e8e8e8;
    border-radius: 6px;
    cursor: pointer;
    transition: background 0.1s;
}

.channel-item:hover {
    background: #f8f8f8;
}

.channel-name {
    font-family: monospace;
    color: #444;
}

.muted-badge {
    margin-left: auto;
    font-size: 0.75rem;
    color: #999;
    background: #f0f0f0;
    padding: 0.15rem 0.5rem;
    border-radius: 10px;
}

/* ─── Expandable panel ─── */

.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.85rem 1rem;
    border: none;
    background: none;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    color: #333;
}

.panel-header:hover {
    background: #f8f8f8;
}

.panel-chevron {
    transition: transform 0.2s;
    font-size: 1rem;
}

.panel-chevron.open {
    transform: rotate(90deg);
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e8e8e8;
}

.field-error {
    color: #dc3545;
    font-size: 0.85rem;
    margin: 0.25rem 0 0.75rem;
}

/* ─── Status badges ─── */

.status-badge {
    display: inline-block;
    font-size: 0.75rem;
    padding: 0.2rem 0.6rem;
    border-radius: 10px;
    margin-left: 0.5rem;
    font-weight: 500;
}

.status-on {
    background: #d4edda;
    color: #155724;
}

.status-off {
    background: #f8d7da;
    color: #721c24;
}

.hint-text {
    font-size: 0.85rem;
    color: #888;
    margin-top: 0.5rem;
}

.current-badge {
    font-size: 0.8rem;
    color: #1a73e8;
    font-weight: 500;
}

/* ─── Sessions table ─── */

.table-responsive {
    overflow-x: auto;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    background: #fff;
    border-radius: 8px;
    overflow: hidden;
    border: 1px solid #e0e0e0;
}

.sessions-table th {
    background: #f8f9fa;
    text-align: left;
    padding: 0.65rem 1rem;
    font-size: 0.8rem;
    text-transform: uppercase;
    color: #666;
    font-weight: 600;
    letter-spacing: 0.03em;
}

.sessions-table td {
    padding: 0.7rem 1rem;
    border-top: 1px solid #f0f0f0;
    font-size: 0.9rem;
    color: #333;
}

/* ─── Modal ─── */

.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    border-radius: 10px;
    padding: 1.5rem 2rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.15);
}

.modal-dialog h4 {
    margin: 0 0 0.5rem;
}

.modal-dialog p {
    color: #555;
    margin-bottom: 1.25rem;
}

/* ─── Radio group ─── */

.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.925rem;
}

/* ─── Appearance preview ─── */

.appearance-preview {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    transition: all 0.25s;
}

.preview-header {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.preview-body {
    margin-bottom: 1rem;
    line-height: 1.5;
}

.preview-actions {
    display: flex;
    gap: 0.5rem;
}

.preview-btn {
    padding: 0.4rem 1rem;
    border-radius: 5px;
    border: none;
    cursor: pointer;
    font-size: 0.85rem;
    font-weight: 500;
}

.preview-btn.primary {
    background: #1a73e8;
    color: #fff;
}

.preview-btn.secondary {
    background: #e8e8e8;
    color: #333;
}

/* Theme variants */
.preview-theme-light {
    background: #fff;
    color: #222;
}

.preview-theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-theme-dark .preview-btn.secondary {
    background: #444;
    color: #ddd;
}

.preview-theme-system {
    background: linear-gradient(135deg, #fff 50%, #1e1e2e 50%);
    color: #222;
}

/* Font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-compact {
    padding: 0.65rem;
    line-height: 1.2;
}

.preview-compact .preview-body {
    margin-bottom: 0.5rem;
}

/* ─── Toast ─── */

.toast-message {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    padding: 0.75rem 1.25rem;
    border-radius: 8px;
    font-size: 0.9rem;
    font-weight: 500;
    color: #fff;
    z-index: 2000;
    animation: toastIn 0.3s ease;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.15);
}

.toast-success {
    background: #28a745;
}

.toast-error {
    background: #dc3545;
}

@keyframes toastIn {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ─── Loading ─── */

.loading-spinner {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 4rem;
    color: #888;
}

.spinner {
    width: 36px;
    height: 36px;
    border: 3px solid #e0e0e0;
    border-top-color: #1a73e8;
    border-radius: 50%;
    animation: spin 0.7s linear infinite;
    margin-bottom: 1rem;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

@page "/settings"
@using sv_5a84828286dc464db1d58fa1676c4993.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <aside class="settings-sidebar">
        <h3 class="sidebar-title">Settings</h3>
        <nav class="sidebar-nav">
            @foreach (var section in _sections)
            {
                <button class="sidebar-item @(section == _activeSection ? "active" : "")"
                        @onclick="() => SetActiveSection(section)">
                    <span class="sidebar-icon">@GetSectionIcon(section)</span>
                    @section
                </button>
            }
        </nav>
    </aside>

    <main class="settings-main">
        @if (_loading)
        {
            <div class="loading-spinner">
                <div class="spinner"></div>
                <p>Loading settings…</p>
            </div>
        }
        else
        {
            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (_toastVisible)
        {
            <div class="toast-message @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastText
            </div>
        }
    </main>
</div>

@* ─── Section render fragments ─── *@

@{
    RenderFragment RenderProfileSection() =>
        @<section class="settings-section">
            <h2>Profile</h2>
            <p class="section-description">Manage your personal information and public profile.</p>

            <div class="avatar-area">
                <img src="@_profileAvatarUrl" alt="Avatar" class="avatar-preview" />
                <div class="avatar-url-display">
                    <label>Avatar URL</label>
                    <input type="text" value="@_profileAvatarUrl" @onchange="e => _profileAvatarUrl = e.Value?.ToString() ?? string.Empty" />
                </div>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_profileDisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_profileEmail" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="_profileBio"></textarea>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>;

    RenderFragment RenderNotificationsSection() =>
        @<section class="settings-section">
            <h2>Notifications</h2>
            <p class="section-description">Choose how and when you want to be notified.</p>

            <div class="toggle-group">
                <div class="toggle-row">
                    <label>Email Notifications</label>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_notifEmail" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>
                <div class="toggle-row">
                    <label>Push Notifications</label>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_notifPush" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>
                <div class="toggle-row">
                    <label>Weekly Digest</label>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_notifWeeklyDigest" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>
            </div>

            <h4>Muted Channels</h4>
            <div class="channel-list">
                @foreach (var channel in MockSettingsService.AvailableChannels)
                {
                    var ch = channel;
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(ch)"
                               @onchange="e => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                        <span class="channel-name">#@ch</span>
                        @if (_mutedChannels.Contains(ch))
                        {
                            <span class="muted-badge">muted</span>
                        }
                    </label>
                }
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>;

    RenderFragment RenderSecuritySection() =>
        @<section class="settings-section">
            <h2>Security</h2>
            <p class="section-description">Manage your password, two-factor authentication, and active sessions.</p>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="panel-chevron @(_passwordPanelOpen ? "open" : "")">▸</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm Password</label>
                            <input id="confirmPwd" type="password" @bind="_confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <p class="field-error">@_passwordError</p>
                        }
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-row" style="margin-top:1.5rem;">
                <div>
                    <label>Two-Factor Authentication</label>
                    <span class="status-badge @(_twoFactorEnabled ? "status-on" : "status-off")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <label class="toggle-switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="toggle-slider"></span>
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange != null)
            {
                <p class="hint-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h4 style="margin-top:2rem;">Active Sessions</h4>
            <div class="table-responsive">
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (_securitySettings != null)
                        {
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != _securitySettings.Sessions.FirstOrDefault()?.Id)
                                        {
                                            <button class="btn btn-danger btn-sm"
                                                    @onclick="() => ConfirmRevokeSession(session.Id, session.Device)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>

            @if (_showRevokeConfirm)
            {
                <div class="modal-overlay" @onclick="CancelRevoke">
                    <div class="modal-dialog" @onclick:stopPropagation="true">
                        <h4>Revoke Session</h4>
                        <p>Are you sure you want to revoke the session on <strong>@_revokeDeviceName</strong>? The user will be logged out on that device.</p>
                        <div class="button-row">
                            <button class="btn btn-danger" @onclick="ExecuteRevoke">Revoke</button>
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>;

    RenderFragment RenderAppearanceSection() =>
        @<section class="settings-section">
            <h2>Appearance</h2>
            <p class="section-description">Customize how the application looks and feels.</p>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        var t = theme;
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@t"
                                   checked="@(_appTheme == t)"
                                   @onchange="() => _appTheme = t" />
                            @t
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        var s = size;
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@s"
                                   checked="@(_appFontSize == s)"
                                   @onchange="() => _appFontSize = s" />
                            @s
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_appLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Portuguese">Portuguese</option>
                </select>
            </div>

            <div class="toggle-row">
                <label>Compact Mode</label>
                <label class="toggle-switch">
                    <input type="checkbox" @bind="_appCompactMode" />
                    <span class="toggle-slider"></span>
                </label>
            </div>

            <h4 style="margin-top:1.5rem;">Preview</h4>
            <div class="appearance-preview @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-body">This is a preview of your selected appearance settings. The theme, font size, and compact mode are reflected here.</p>
                <div class="preview-actions">
                    <button class="preview-btn primary">Primary Action</button>
                    <button class="preview-btn secondary">Secondary</button>
                </div>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>;
}

@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";
    private bool _loading = true;

    // Toast
    private bool _toastVisible;
    private string _toastText = string.Empty;
    private bool _toastIsError;

    // Profile
    private string _profileDisplayName = string.Empty;
    private string _profileEmail = string.Empty;
    private string _profileAvatarUrl = string.Empty;
    private string _profileBio = string.Empty;
    private UserProfile? _savedProfile;

    // Notifications
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifWeeklyDigest;
    private List<string> _mutedChannels = [];

    // Security
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelOpen;
    private string _currentPassword = string.Empty;
    private string _newPassword = string.Empty;
    private string _confirmPassword = string.Empty;
    private string _passwordError = string.Empty;
    private bool _twoFactorEnabled;
    private bool _showRevokeConfirm;
    private string _revokeSessionId = string.Empty;
    private string _revokeDeviceName = string.Empty;

    // Appearance
    private string _appTheme = "Light";
    private string _appFontSize = "Medium";
    private string _appLanguage = "English";
    private bool _appCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        ApplyProfile(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        _notifEmail = notifs.EmailNotifications;
        _notifPush = notifs.PushNotifications;
        _notifWeeklyDigest = notifs.WeeklyDigest;
        _mutedChannels = new List<string>(notifs.MutedChannels);

        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        var appearance = await SettingsService.GetAppearanceAsync();
        _appTheme = appearance.Theme;
        _appFontSize = appearance.FontSize;
        _appLanguage = appearance.Language;
        _appCompactMode = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    private void SetActiveSection(string section) => _activeSection = section;

    // ─── Profile ───

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully.");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile != null)
        {
            ApplyProfile(_savedProfile);
        }
    }

    // ─── Notifications ───

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifWeeklyDigest, new List<string>(_mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved.");
    }

    // ─── Security ───

    private async Task UpdatePassword()
    {
        _passwordError = string.Empty;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = string.Empty;
        _newPassword = string.Empty;
        _confirmPassword = string.Empty;
        _passwordPanelOpen = false;
        await ShowToast("Password updated successfully.");
    }

    private void ConfirmRevokeSession(string sessionId, string deviceName)
    {
        _revokeSessionId = sessionId;
        _revokeDeviceName = deviceName;
        _showRevokeConfirm = true;
    }

    private async Task ExecuteRevoke()
    {
        await SettingsService.RevokeSessionAsync(_revokeSessionId);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _showRevokeConfirm = false;
        await ShowToast("Session revoked.");
    }

    private void CancelRevoke() => _showRevokeConfirm = false;

    // ─── Appearance ───

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_appTheme.ToLowerInvariant()} preview-font-{_appFontSize.ToLowerInvariant()}";
        if (_appCompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_appTheme, _appFontSize, _appLanguage, _appCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved.");
    }

    // ─── Helpers ───

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private async Task ShowToast(string text, bool isError = false)
    {
        _toastText = text;
        _toastIsError = isError;
        _toastVisible = true;
        StateHasChanged();
        await Task.Delay(3000);
        _toastVisible = false;
        StateHasChanged();
    }
}

/* ─── Layout ─── */

.settings-container {
    display: flex;
    min-height: calc(100vh - 3.5rem);
    background: #f8f9fa;
}

.settings-sidebar {
    width: 240px;
    background: #fff;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.sidebar-title {
    font-size: 1.1rem;
    font-weight: 600;
    padding: 0 1.25rem 1rem;
    margin: 0;
    color: #333;
}

.sidebar-nav {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.7rem 1.25rem;
    border: none;
    background: none;
    font-size: 0.925rem;
    color: #555;
    cursor: pointer;
    text-align: left;
    transition: background 0.15s, color 0.15s;
    width: 100%;
}

.sidebar-item:hover {
    background: #f0f0f0;
    color: #111;
}

.sidebar-item.active {
    background: #e8f0fe;
    color: #1a73e8;
    font-weight: 600;
    border-left: 3px solid #1a73e8;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* ─── Main content ─── */

.settings-main {
    flex: 1;
    padding: 2rem 2.5rem;
    position: relative;
    max-width: 800px;
}

.settings-section h2 {
    margin: 0 0 0.25rem;
    font-size: 1.5rem;
    color: #222;
}

.section-description {
    color: #666;
    margin-bottom: 1.5rem;
}

/* ─── Forms ─── */

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.35rem;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.55rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.925rem;
    transition: border-color 0.15s;
    background: #fff;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #1a73e8;
    box-shadow: 0 0 0 3px rgba(26, 115, 232, 0.12);
}

/* ─── Buttons ─── */

.button-row {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.55rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    border: 1px solid transparent;
    transition: background 0.15s, box-shadow 0.15s;
}

.btn-primary {
    background: #1a73e8;
    color: #fff;
}

.btn-primary:hover {
    background: #1557b0;
}

.btn-secondary {
    background: #fff;
    color: #333;
    border-color: #ccc;
}

.btn-secondary:hover {
    background: #f5f5f5;
}

.btn-danger {
    background: #dc3545;
    color: #fff;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* ─── Avatar ─── */

.avatar-area {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e0e0e0;
}

.avatar-url-display {
    flex: 1;
}

.avatar-url-display label {
    display: block;
    font-weight: 500;
    font-size: 0.85rem;
    margin-bottom: 0.3rem;
    color: #555;
}

.avatar-url-display input {
    width: 100%;
    padding: 0.45rem 0.65rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.85rem;
}

/* ─── Toggle switches ─── */

.toggle-group {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 0.25rem 0;
    margin-bottom: 1.5rem;
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.85rem 1rem;
}

.toggle-group .toggle-row + .toggle-row {
    border-top: 1px solid #f0f0f0;
}

.toggle-switch {
    position: relative;
    display: inline-block;
    width: 44px;
    height: 24px;
    flex-shrink: 0;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.toggle-slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background: #ccc;
    border-radius: 24px;
    transition: background 0.2s;
}

.toggle-slider::before {
    content: "";
    position: absolute;
    width: 18px;
    height: 18px;
    left: 3px;
    bottom: 3px;
    background: #fff;
    border-radius: 50%;
    transition: transform 0.2s;
}

.toggle-switch input:checked + .toggle-slider {
    background: #1a73e8;
}

.toggle-switch input:checked + .toggle-slider::before {
    transform: translateX(20px);
}

/* ─── Channels ─── */

.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.5rem 0.75rem;
    background: #fff;
    border: 1px solid #e8e8e8;
    border-radius: 6px;
    cursor: pointer;
    transition: background 0.1s;
}

.channel-item:hover {
    background: #f8f8f8;
}

.channel-name {
    font-family: monospace;
    color: #444;
}

.muted-badge {
    margin-left: auto;
    font-size: 0.75rem;
    color: #999;
    background: #f0f0f0;
    padding: 0.15rem 0.5rem;
    border-radius: 10px;
}

/* ─── Expandable panel ─── */

.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.85rem 1rem;
    border: none;
    background: none;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    color: #333;
}

.panel-header:hover {
    background: #f8f8f8;
}

.panel-chevron {
    transition: transform 0.2s;
    font-size: 1rem;
}

.panel-chevron.open {
    transform: rotate(90deg);
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e8e8e8;
}

.field-error {
    color: #dc3545;
    font-size: 0.85rem;
    margin: 0.25rem 0 0.75rem;
}

/* ─── Status badges ─── */

.status-badge {
    display: inline-block;
    font-size: 0.75rem;
    padding: 0.2rem 0.6rem;
    border-radius: 10px;
    margin-left: 0.5rem;
    font-weight: 500;
}

.status-on {
    background: #d4edda;
    color: #155724;
}

.status-off {
    background: #f8d7da;
    color: #721c24;
}

.hint-text {
    font-size: 0.85rem;
    color: #888;
    margin-top: 0.5rem;
}

.current-badge {
    font-size: 0.8rem;
    color: #1a73e8;
    font-weight: 500;
}

/* ─── Sessions table ─── */

.table-responsive {
    overflow-x: auto;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    background: #fff;
    border-radius: 8px;
    overflow: hidden;
    border: 1px solid #e0e0e0;
}

.sessions-table th {
    background: #f8f9fa;
    text-align: left;
    padding: 0.65rem 1rem;
    font-size: 0.8rem;
    text-transform: uppercase;
    color: #666;
    font-weight: 600;
    letter-spacing: 0.03em;
}

.sessions-table td {
    padding: 0.7rem 1rem;
    border-top: 1px solid #f0f0f0;
    font-size: 0.9rem;
    color: #333;
}

/* ─── Modal ─── */

.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    border-radius: 10px;
    padding: 1.5rem 2rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.15);
}

.modal-dialog h4 {
    margin: 0 0 0.5rem;
}

.modal-dialog p {
    color: #555;
    margin-bottom: 1.25rem;
}

/* ─── Radio group ─── */

.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.925rem;
}

/* ─── Appearance preview ─── */

.appearance-preview {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    transition: all 0.25s;
}

.preview-header {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.preview-body {
    margin-bottom: 1rem;
    line-height: 1.5;
}

.preview-actions {
    display: flex;
    gap: 0.5rem;
}

.preview-btn {
    padding: 0.4rem 1rem;
    border-radius: 5px;
    border: none;
    cursor: pointer;
    font-size: 0.85rem;
    font-weight: 500;
}

.preview-btn.primary {
    background: #1a73e8;
    color: #fff;
}

.preview-btn.secondary {
    background: #e8e8e8;
    color: #333;
}

/* Theme variants */
.preview-theme-light {
    background: #fff;
    color: #222;
}

.preview-theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-theme-dark .preview-btn.secondary {
    background: #444;
    color: #ddd;
}

.preview-theme-system {
    background: linear-gradient(135deg, #fff 50%, #1e1e2e 50%);
    color: #222;
}

/* Font size variants */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-compact {
    padding: 0.65rem;
    line-height: 1.2;
}

.preview-compact .preview-body {
    margin-bottom: 0.5rem;
}

/* ─── Toast ─── */

.toast-message {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    padding: 0.75rem 1.25rem;
    border-radius: 8px;
    font-size: 0.9rem;
    font-weight: 500;
    color: #fff;
    z-index: 2000;
    animation: toastIn 0.3s ease;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.15);
}

.toast-success {
    background: #28a745;
}

.toast-error {
    background: #dc3545;
}

@keyframes toastIn {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ─── Loading ─── */

.loading-spinner {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 4rem;
    color: #888;
}

.spinner {
    width: 36px;
    height: 36px;
    border: 3px solid #e0e0e0;
    border-top-color: #1a73e8;
    border-radius: 50%;
    animation: spin 0.7s linear infinite;
    margin-bottom: 1rem;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

toolCalls.args:
{"file_text": "@page "/settings"
@using sv_5a84828286dc464db1d58fa1676c4993.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <aside class="settings-sidebar">
        <h3 class="sidebar-title">Settings</h3>
        <nav class="sidebar-nav">
            @foreach (var section in _sections)
            {
                <button class="sidebar-item @(section == _activeSection ? "active" : "")"
                        @onclick="() => SetActiveSection(section)">
                    <span class="sidebar-icon">@GetSectionIcon(section)</span>
                    @section
                </button>
            }
        </nav>
    </aside>

    <main class="settings-main">
        @if (_loading)
        {
            <div class="loading-spinner">
                <div class="spinner"></div>
                <p>Loading settings…</p>
            </div>
        }
        else
        {
            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (_toastVisible)
        {
            <div class="toast-message @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastText
            </div>
        }
    </main>
</div>

@* ─── Section render fragments ─── *@

@{
    RenderFragment RenderProfileSection() =>
        @<section class="settings-section">
            <h2>Profile</h2>
            <p class="section-description">Manage your personal information and public profile.</p>

            <div class="avatar-area">
                <img src="@_profileAvatarUrl" alt="Avatar" class="avatar-preview" />
                <div class="avatar-url-display">
                    <label>Avatar URL</label>
                    <input type="text" value="@_profileAvatarUrl" @onchange="e => _profileAvatarUrl = e.Value?.ToString() ?? string.Empty" />
                </div>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_profileDisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_profileEmail" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="_profileBio"></textarea>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>;

    RenderFragment RenderNotificationsSection() =>
        @<section class="settings-section">
            <h2>Notifications</h2>
            <p class="section-description">Choose how and when you want to be notified.</p>

            <div class="toggle-group">
                <div class="toggle-row">
                    <label>Email Notifications</label>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_notifEmail" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>
                <div class="toggle-row">
                    <label>Push Notifications</label>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_notifPush" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>
                <div class="toggle-row">
                    <label>Weekly Digest</label>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_notifWeeklyDigest" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>
            </div>

            <h4>Muted Channels</h4>
            <div class="channel-list">
                @foreach (var channel in MockSettingsService.AvailableChannels)
                {
                    var ch = channel;
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(ch)"
                               @onchange="e => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                        <span class="channel-name">#@ch</span>
                        @if (_mutedChannels.Contains(ch))
                        {
                            <span class="muted-badge">muted</span>
                        }
                    </label>
                }
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>;

    RenderFragment RenderSecuritySection() =>
        @<section class="settings-section">
            <h2>Security</h2>
            <p class="section-description">Manage your password, two-factor authentication, and active sessions.</p>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="panel-chevron @(_passwordPanelOpen ? "open" : "")">▸</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm Password</label>
                            <input id="confirmPwd" type="password" @bind="_confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <p class="field-error">@_passwordError</p>
                        }
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-row" style="margin-top:1.5rem;">
                <div>
                    <label>Two-Factor Authentication</label>
                    <span class="status-badge @(_twoFactorEnabled ? "status-on" : "status-off")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <label class="toggle-switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="toggle-slider"></span>
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange != null)
            {
                <p class="hint-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h4 style="margin-top:2rem;">Active Sessions</h4>
            <div class="table-responsive">
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (_securitySettings != null)
                        {
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != _securitySettings.Sessions.FirstOrDefault()?.Id)
                                        {
                                            <button class="btn btn-danger btn-sm"
                                                    @onclick="() => ConfirmRevokeSession(session.Id, session.Device)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>

            @if (_showRevokeConfirm)
            {
                <div class="modal-overlay" @onclick="CancelRevoke">
                    <div class="modal-dialog" @onclick:stopPropagation="true">
                        <h4>Revoke Session</h4>
                        <p>Are you sure you want to revoke the session on <strong>@_revokeDeviceName</strong>? The user will be logged out on that device.</p>
                        <div class="button-row">
                            <button class="btn btn-danger" @onclick="ExecuteRevoke">Revoke</button>
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>;

    RenderFragment RenderAppearanceSection() =>
        @<section class="settings-section">
            <h2>Appearance</h2>
            <p class="section-description">Customize how the application looks and feels.</p>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        var t = theme;
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@t"
                                   checked="@(_appTheme == t)"
                                   @onchange="() => _appTheme = t" />
                            @t
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        var s = size;
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@s"
                                   checked="@(_appFontSize == s)"
                                   @onchange="() => _appFontSize = s" />
                            @s
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_appLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Portuguese">Portuguese</option>
                </select>
            </div>

            <div class="toggle-row">
                <label>Compact Mode</label>
                <label class="toggle-switch">
                    <input type="checkbox" @bind="_appCompactMode" />
                    <span class="toggle-slider"></span>
                </label>
            </div>

            <h4 style="margin-top:1.5rem;">Preview</h4>
            <div class="appearance-preview @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-body">This is a preview of your selected appearance settings. The theme, font size, and compact mode are reflected here.</p>
                <div class="preview-actions">
                    <button class="preview-btn primary">Primary Action</button>
                    <button class="preview-btn secondary">Secondary</button>
                </div>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>;
}

@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";
    private bool _loading = true;

    // Toast
    private bool _toastVisible;
    private string _toastText = string.Empty;
    private bool _toastIsError;

    // Profile
    private string _profileDisplayName = string.Empty;
    private string _profileEmail = string.Empty;
    private string _profileAvatarUrl = string.Empty;
    private string _profileBio = string.Empty;
    private UserProfile? _savedProfile;

    // Notifications
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifWeeklyDigest;
    private List<string> _mutedChannels = [];

    // Security
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelOpen;
    private string _currentPassword = string.Empty;
    private string _newPassword = string.Empty;
    private string _confirmPassword = string.Empty;
    private string _passwordError = string.Empty;
    private bool _twoFactorEnabled;
    private bool _showRevokeConfirm;
    private string _revokeSessionId = string.Empty;
    private string _revokeDeviceName = string.Empty;

    // Appearance
    private string _appTheme = "Light";
    private string _appFontSize = "Medium";
    private string _appLanguage = "English";
    private bool _appCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        ApplyProfile(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        _notifEmail = notifs.EmailNotifications;
        _notifPush = notifs.PushNotifications;
        _notifWeeklyDigest = notifs.WeeklyDigest;
        _mutedChannels = new List<string>(notifs.MutedChannels);

        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        var appearance = await SettingsService.GetAppearanceAsync();
        _appTheme = appearance.Theme;
        _appFontSize = appearance.FontSize;
        _appLanguage = appearance.Language;
        _appCompactMode = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    private void SetActiveSection(string section) => _activeSection = section;

    // ─── Profile ───

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully.");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile != null)
        {
            ApplyProfile(_savedProfile);
        }
    }

    // ─── Notifications ───

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifWeeklyDigest, new List<string>(_mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved.");
    }

    // ─── Security ───

    private async Task UpdatePassword()
    {
        _passwordError = string.Empty;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = string.Empty;
        _newPassword = string.Empty;
        _confirmPassword = string.Empty;
        _passwordPanelOpen = false;
        await ShowToast("Password updated successfully.");
    }

    private void ConfirmRevokeSession(string sessionId, string deviceName)
    {
        _revokeSessionId = sessionId;
        _revokeDeviceName = deviceName;
        _showRevokeConfirm = true;
    }

    private async Task ExecuteRevoke()
    {
        await SettingsService.RevokeSessionAsync(_revokeSessionId);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _showRevokeConfirm = false;
        await ShowToast("Session revoked.");
    }

    private void CancelRevoke() => _showRevokeConfirm = false;

    // ─── Appearance ───

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_appTheme.ToLowerInvariant()} preview-font-{_appFontSize.ToLowerInvariant()}";
        if (_appCompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_appTheme, _appFontSize, _appLanguage, _appCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved.");
    }

