+}
+
+/* ─── Expandable panel ─── */
+
+.expandable-panel {
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    overflow: hidden;
+    background: #fff;
+}
+
+.panel-header {
+    display: flex;
