+
+/* ─── Sessions table ─── */
+
+.table-responsive {
+    overflow-x: auto;
+}
+
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    background: #fff;
+    border-radius: 8px;
+    overflow: hidden;
+    border: 1px solid #e0e0e0;
+}
+
+.sessions-table th {
+    background: #f8f9fa;
+    text-align: left;
+    padding: 0.65rem 1rem;
+    font-size: 0.8rem;
+    text-transform: uppercase;
