+}
+
+.sessions-table td {
+    padding: 0.7rem 1rem;
+    border-top: 1px solid #f0f0f0;
+    font-size: 0.9rem;
+    color: #333;
+}
+
+/* ─── Modal ─── */
+
+.modal-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.4);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.modal-dialog {
+    background: #fff;
+    border-radius: 10px;
+    padding: 1.5rem 2rem;
+    max-width: 420px;
+    width: 90%;
+    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.15);
+}
+
+.modal-dialog h4 {
+    margin: 0 0 0.5rem;
+}
+
+.modal-dialog p {
+    color: #555;
+    margin-bottom: 1.25rem;
