+}
+
+.preview-actions {
+    display: flex;
+    gap: 0.5rem;
+}
+
+.preview-btn {
+    padding: 0.4rem 1rem;
+    border-radius: 5px;
+    border: none;
+    cursor: pointer;
+    font-size: 0.85rem;
+    font-weight: 500;
+}
+
+.preview-btn.primary {
+    background: #1a73e8;
+    color: #fff;
+}
+
+.preview-btn.secondary {
+    background: #e8e8e8;
+    color: #333;
+}
+
+/* Theme variants */
+.preview-theme-light {
+    background: #fff;
+    color: #222;
+}
+
+.preview-theme-dark {
+    background: #1e1e2e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.preview-theme-dark .preview-btn.secondary {
+    background: #444;
+    color: #ddd;
+}
+
+.preview-theme-system {
+    background: linear-gradient(135deg, #fff 50%, #1e1e2e 50%);
