+}
+
+/* Font size variants */
+.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.2rem;
+}
+
+/* Compact mode */
+.preview-compact {
+    padding: 0.65rem;
+    line-height: 1.2;
+}
+
+.preview-compact .preview-body {
+    margin-bottom: 0.5rem;
+}
+
+/* ─── Toast ─── */
+
+.toast-message {
+    position: fixed;
+    bottom: 1.5rem;
+    right: 1.5rem;
+    padding: 0.75rem 1.25rem;
+    border-radius: 8px;
