toolArgs.file_text:
@page "/settings"
@using sv_5a84828286dc464db1d58fa1676c4993.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <aside class="settings-sidebar">
        <h3 class="sidebar-title">Settings</h3>
        <nav class="sidebar-nav">
            @foreach (var section in _sections)
            {
                <button class="sidebar-item @(section == _activeSection ? "active" : "")"
                        @onclick="() => SetActiveSection(section)">
                    <span class="sidebar-icon">@GetSectionIcon(section)</span>
                    @section
                </button>
            }
        </nav>
    </aside>

    <main class="settings-main">
        @if (_loading)
        {
            <div class="loading-spinner">
                <div class="spinner"></div>
                <p>Loading settings…</p>
            </div>
        }
        else
        {
            @switch (_activeSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (_toastVisible)
        {
            <div class="toast-message @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastText
            </div>
        }
    </main>
</div>

@* ─── Section render fragments ─── *@

@{
    RenderFragment RenderProfileSection() =>
        @<section class="settings-section">
            <h2>Profile</h2>
            <p class="section-description">Manage your personal information and public profile.</p>

            <div class="avatar-area">
                <img src="@_profileAvatarUrl" alt="Avatar" class="avatar-preview" />
                <div class="avatar-url-display">
                    <label>Avatar URL</label>
                    <input type="text" value="@_profileAvatarUrl" @onchange="e => _profileAvatarUrl = e.Value?.ToString() ?? string.Empty" />
                </div>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_profileDisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_profileEmail" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="_profileBio"></textarea>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>;

    RenderFragment RenderNotificationsSection() =>
        @<section class="settings-section">
            <h2>Notifications</h2>
            <p class="section-description">Choose how and when you want to be notified.</p>

            <div class="toggle-group">
                <div class="toggle-row">
                    <label>Email Notifications</label>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_notifEmail" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>
                <div class="toggle-row">
                    <label>Push Notifications</label>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_notifPush" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>
                <div class="toggle-row">
                    <label>Weekly Digest</label>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_notifWeeklyDigest" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>
            </div>

            <h4>Muted Channels</h4>
            <div class="channel-list">
                @foreach (var channel in MockSettingsService.AvailableChannels)
                {
                    var ch = channel;
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(ch)"
                               @onchange="e => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                        <span class="channel-name">#@ch</span>
                        @if (_mutedChannels.Contains(ch))
                        {
                            <span class="muted-badge">muted</span>
                        }
                    </label>
                }
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>;

    RenderFragment RenderSecuritySection() =>
        @<section class="settings-section">
            <h2>Security</h2>
            <p class="section-description">Manage your password, two-factor authentication, and active sessions.</p>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="panel-chevron @(_passwordPanelOpen ? "open" : "")">▸</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm Password</label>
                            <input id="confirmPwd" type="password" @bind="_confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <p class="field-error">@_passwordError</p>
                        }
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-row" style="margin-top:1.5rem;">
                <div>
                    <label>Two-Factor Authentication</label>
                    <span class="status-badge @(_twoFactorEnabled ? "status-on" : "status-off")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <label class="toggle-switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="toggle-slider"></span>
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange != null)
            {
                <p class="hint-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h4 style="margin-top:2rem;">Active Sessions</h4>
            <div class="table-responsive">
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (_securitySettings != null)
                        {
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != _securitySettings.Sessions.FirstOrDefault()?.Id)
                                        {
                                            <button class="btn btn-danger btn-sm"
                                                    @onclick="() => ConfirmRevokeSession(session.Id, session.Device)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>

            @if (_showRevokeConfirm)
            {
                <div class="modal-overlay" @onclick="CancelRevoke">
                    <div class="modal-dialog" @onclick:stopPropagation="true">
                        <h4>Revoke Session</h4>
                        <p>Are you sure you want to revoke the session on <strong>@_revokeDeviceName</strong>? The user will be logged out on that device.</p>
                        <div class="button-row">
                            <button class="btn btn-danger" @onclick="ExecuteRevoke">Revoke</button>
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>;

    RenderFragment RenderAppearanceSection() =>
        @<section class="settings-section">
            <h2>Appearance</h2>
            <p class="section-description">Customize how the application looks and feels.</p>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        var t = theme;
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@t"
                                   checked="@(_appTheme == t)"
                                   @onchange="() => _appTheme = t" />
                            @t
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        var s = size;
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@s"
                                   checked="@(_appFontSize == s)"
                                   @onchange="() => _appFontSize = s" />
                            @s
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_appLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Portuguese">Portuguese</option>
                </select>
            </div>

            <div class="toggle-row">
                <label>Compact Mode</label>
                <label class="toggle-switch">
                    <input type="checkbox" @bind="_appCompactMode" />
                    <span class="toggle-slider"></span>
                </label>
            </div>

            <h4 style="margin-top:1.5rem;">Preview</h4>
            <div class="appearance-preview @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-body">This is a preview of your selected appearance settings. The theme, font size, and compact mode are reflected here.</p>
                <div class="preview-actions">
                    <button class="preview-btn primary">Primary Action</button>
                    <button class="preview-btn secondary">Secondary</button>
                </div>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>;
}

@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";
    private bool _loading = true;

    // Toast
    private bool _toastVisible;
    private string _toastText = string.Empty;
    private bool _toastIsError;

    // Profile
    private string _profileDisplayName = string.Empty;
    private string _profileEmail = string.Empty;
    private string _profileAvatarUrl = string.Empty;
    private string _profileBio = string.Empty;
    private UserProfile? _savedProfile;

    // Notifications
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifWeeklyDigest;
    private List<string> _mutedChannels = [];

    // Security
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelOpen;
    private string _currentPassword = string.Empty;
    private string _newPassword = string.Empty;
    private string _confirmPassword = string.Empty;
    private string _passwordError = string.Empty;
    private bool _twoFactorEnabled;
    private bool _showRevokeConfirm;
    private string _revokeSessionId = string.Empty;
    private string _revokeDeviceName = string.Empty;

    // Appearance
    private string _appTheme = "Light";
    private string _appFontSize = "Medium";
    private string _appLanguage = "English";
    private bool _appCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        ApplyProfile(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        _notifEmail = notifs.EmailNotifications;
        _notifPush = notifs.PushNotifications;
        _notifWeeklyDigest = notifs.WeeklyDigest;
        _mutedChannels = new List<string>(notifs.MutedChannels);

        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        var appearance = await SettingsService.GetAppearanceAsync();
        _appTheme = appearance.Theme;
        _appFontSize = appearance.FontSize;
        _appLanguage = appearance.Language;
        _appCompactMode = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    private void SetActiveSection(string section) => _activeSection = section;

    // ─── Profile ───

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully.");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile != null)
        {
            ApplyProfile(_savedProfile);
        }
    }

    // ─── Notifications ───

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifWeeklyDigest, new List<string>(_mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved.");
    }

    // ─── Security ───

    private async Task UpdatePassword()
    {
        _passwordError = string.Empty;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = string.Empty;
        _newPassword = string.Empty;
        _confirmPassword = string.Empty;
        _passwordPanelOpen = false;
        await ShowToast("Password updated successfully.");
    }

    private void ConfirmRevokeSession(string sessionId, string deviceName)
    {
        _revokeSessionId = sessionId;
        _revokeDeviceName = deviceName;
        _showRevokeConfirm = true;
    }

    private async Task ExecuteRevoke()
    {
        await SettingsService.RevokeSessionAsync(_revokeSessionId);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _showRevokeConfirm = false;
        await ShowToast("Session revoked.");
    }

    private void CancelRevoke() => _showRevokeConfirm = false;

    // ─── Appearance ───

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_appTheme.ToLowerInvariant()} preview-font-{_appFontSize.ToLowerInvariant()}";
        if (_appCompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_appTheme, _appFontSize, _appLanguage, _appCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved.");
    }

    // ─── Helpers ───

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private async Task ShowToast(string text, bool isError = false)
    {
        _toastText = text;
        _toastIsError = isError;
        _toastVisible = true;
        StateHasChanged();
        await Task.Delay(3000);
        _toastVisible = false;
        StateHasChanged();
    }
}

